CREATE TABLE locations (id INTEGER PRIMARY KEY, qr_code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, zone TEXT, area_type TEXT, lat REAL NOT NULL, lon REAL NOT NULL, active INTEGER DEFAULT 1);
CREATE TABLE teams (id INTEGER PRIMARY KEY, name TEXT NOT NULL, lat REAL NOT NULL, lon REAL NOT NULL, available INTEGER DEFAULT 1, active INTEGER DEFAULT 1, updated_at TEXT);
CREATE TABLE workers (id INTEGER PRIMARY KEY, team_id INTEGER REFERENCES teams(id), name TEXT NOT NULL, worker_code TEXT UNIQUE NOT NULL, phone TEXT, active INTEGER DEFAULT 1);
CREATE TABLE reports (id INTEGER PRIMARY KEY, ticket TEXT UNIQUE NOT NULL, location_id INTEGER REFERENCES locations(id), location_text TEXT, is_custom_location INTEGER DEFAULT 0, qr_source_location_id INTEGER, assigned_zone TEXT, supervisor_notes TEXT, category TEXT NOT NULL, description TEXT, language TEXT, contact TEXT, reporter_photo TEXT, priority INTEGER DEFAULT 30, status TEXT DEFAULT 'PENDING', created_at TEXT);
CREATE TABLE tasks (id INTEGER PRIMARY KEY, report_id INTEGER NOT NULL REFERENCES reports(id), team_id INTEGER REFERENCES teams(id), worker_id INTEGER REFERENCES workers(id), status TEXT, assigned_at TEXT, accepted_at TEXT, started_at TEXT, completed_at TEXT, distance_m REAL, before_photo TEXT, after_photo TEXT);
CREATE TABLE status_history (id INTEGER PRIMARY KEY, report_id INTEGER, task_id INTEGER, old_status TEXT, new_status TEXT, actor TEXT, changed_at TEXT);
